mapper.select:
SELECT  FROM agent_subagent_task
WHERE tenant_id=#{tenantId} AND parent_run_id=#{parentRunId} AND function_call_id=#{functionCallId}
  AND deleted=0 ORDER BY id ASC

SELECT FROM agent_subagent_task WHERE tenant_id=#{tenantId} AND parent_run_id=#{parentRunId} AND deleted=0
AND task_id IN #{taskId}
ORDER BY id ASC

mapper.update:
UPDATE agent_subagent_task SET child_session_id=#{childSessionId}
WHERE tenant_id=#{tenantId} AND task_id=#{taskId} AND status='RUNNING'
  AND lease_owner=#{workerId} AND fencing_token=#{fencingToken} AND deleted=0

UPDATE agent_subagent_task SET lease_expires_at=#{leaseExpiresAt}
WHERE tenant_id=#{tenantId} AND task_id=#{taskId} AND status='RUNNING' AND lease_owner=#{workerId}
  AND fencing_token=#{fencingToken} AND lease_expires_at >= #{now} AND deleted=0

UPDATE agent_subagent_task SET status='CANCELLED', completed_at=#{cancelledAt}, lease_owner=NULL, lease_expires_at=NULL
WHERE tenant_id=#{tenantId} AND parent_run_id=#{parentRunId} AND status IN ('READY','RUNNING') AND deleted=0
  AND task_id IN #{taskId}

UPDATE agent_orchestration_outbox SET status='PUBLISHED',published_at=#{publishedAt},lease_owner=NULL,lease_expires_at=NULL
WHERE tenant_id=#{tenantId} AND event_id=#{eventId} AND status='PUBLISHING' AND lease_owner=#{owner}
  AND fencing_token=#{fencingToken} AND deleted=0

mapper.select:
SELECT  FROM agent_subagent_task
WHERE status='RUNNING' AND lease_expires_at < #{now} AND deleted=0
ORDER BY lease_expires_at ASC LIMIT #{limit}

SELECT  FROM agent_subagent_task
WHERE callback_status='DELIVERING' AND callback_claimed_at < #{staleBefore} AND deleted=0
ORDER BY callback_claimed_at ASC LIMIT #{limit}

mapper.update:
UPDATE agent_subagent_task SET callback_status='DEAD'
WHERE tenant_id=#{tenantId} AND parent_run_id=#{parentRunId} AND task_id=#{taskId}
  AND callback_status='RETRYING' AND callback_attempt >= 12 AND deleted=0
